#!/bin/sh
# Rebases the rename branch (PR "Rename, part 1") onto BASE (default origin/main) without
# resolving the mechanical commit's conflicts by hand: the first commit is regenerated by
# scripts/rename-pi-desk.py on BASE, then the hand-written commits after it are picked again.
# Usage: scripts/rename-pi-desk-rebase.sh [BASE]   (a clean tree; the branch checked out)
#   RENAME_SCRIPT=FILE: regenerate with FILE instead of the branch's scripts/rename-pi-desk.py
set -eu
BASE=${1:-origin/main}
cd "$(git rev-parse --show-toplevel)"
[ -z "$(git status --porcelain)" ] || { echo "rename-rebase: the tree is not clean" >&2; exit 1; }
first=$(git log --format=%H --grep='^Rename, part 1a:' -n 1)
[ -n "$first" ] || { echo "rename-rebase: no 'Rename, part 1a:' commit on this branch" >&2; exit 1; }
msg=$(git log -1 --format=%B "$first")
tmp=$(mktemp -d)
if [ -n "${RENAME_SCRIPT:-}" ]; then cp "$RENAME_SCRIPT" "$tmp/rename.py"; else git show "HEAD:scripts/rename-pi-desk.py" > "$tmp/rename.py"; fi
git show "HEAD:scripts/rename-pi-desk-rebase.sh" > "$tmp/rebase.sh" 2>/dev/null || cp "$0" "$tmp/rebase.sh"
picks=$(git rev-list --reverse "$first"..HEAD)
git reset -q --hard "$BASE"
cp "$tmp/rename.py" scripts/rename-pi-desk.py
cp "$tmp/rebase.sh" scripts/rename-pi-desk-rebase.sh
chmod +x scripts/rename-pi-desk-rebase.sh
python3 scripts/rename-pi-desk.py
python3 scripts/rename-pi-desk.py --check >/dev/null || { echo "rename-rebase: a second run still changes files" >&2; exit 1; }
git add -A
git commit -q -m "$msg"
for c in $picks; do
  git cherry-pick "$c" || { echo "rename-rebase: resolve $c by hand, then: git cherry-pick --continue, and pick the rest: $picks" >&2; exit 1; }
done
rm -rf "$tmp"
echo "rename-rebase: on $(git rev-parse --short "$BASE"): $(git log --oneline "$BASE"..HEAD | wc -l | tr -d ' ') commits"
